import { Gauge } from '@absoluteui/components/gauge';

const host = document.createElement('div');
document.body.append(host);
const gauge = Gauge.create(host, {
  label: 'CPU load',
  value: 72,
  bands: [
    { to: 50, label: 'Normal', color: 3 },
    { to: 80, label: 'Busy', color: 5 },
    { to: 100, label: 'Critical', color: 2 },
  ],
  target: 60,
  valueFormat: { style: 'unit', unit: 'percent' },
});
host.dataset.reading = gauge.valueText;

